"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2031],{61388:e=>{e.exports=JSON.parse('{"functions":[{"name":"getPublicStringAsync","desc":"Filters a player-authored string for public broadcast and returns the safe\\nversion.\\n\\nYields on `TextService:FilterStringAsync()`. Use this for anything a player wrote\\nthat other players will see \u2014 base names, pet names, signs \u2014 since displaying\\nunfiltered text is a Roblox TOS violation.\\n\\nIn Studio or an unpublished place, filtering is attributed to a player actually in\\nthe server, since the real `userId` may not be present. If the server is empty\\nthere, the input is returned **unfiltered** \u2014 so never rely on Studio behaviour to\\nconfirm filtering works.","params":[{"name":"userId","desc":"UserId of whoever wrote the text","lua_type":"number"},{"name":"inputString","desc":"Raw player-authored text","lua_type":"string"}],"returns":[{"desc":"Filtered text safe to broadcast","lua_type":"string"}],"function_type":"static","realm":["Server"],"source":{"line":37,"path":"src/Shared/Class/Sanitation.luau"}}],"properties":[],"types":[],"name":"Sanitation","desc":"Text safety tool for compliance with Roblox TOS.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":9,"path":"src/Shared/Class/Sanitation.luau"}}')}}]);